<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue';import {api,errorText} from '@/lib/api';import {bytes,dateTime,statusLabel} from '@/lib/format'
const state=ref<any>(null),busy=ref(false),error=ref(''),at=ref('');let timer:ReturnType<typeof setInterval>
async function load(){if(busy.value)return;busy.value=true;error.value='';try{state.value=await api('/api/v1/system/status');at.value=new Date().toISOString()}catch(e){error.value=errorText(e)}finally{busy.value=false}}
onMounted(()=>{load();timer=setInterval(()=>{if(!document.hidden)load()},15000)});onBeforeUnmount(()=>clearInterval(timer))
</script>
<template><div class="page-heading"><div><div class="eyebrow">INSTANCE OVERVIEW</div><h1>运行概览</h1><p>查看服务就绪状态、持久存储和待处理积压。</p></div><el-button :loading="busy" @click="load">刷新状态</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/>
 <template v-if="state"><div class="stats-grid"><article class="stat-card"><span>服务状态</span><strong :class="state.ready?'text-success':'text-warning'">{{state.ready?'服务就绪':'需要检查'}}</strong><small>{{state.instanceId}} · v{{state.softwareVersion}}</small></article><article class="stat-card"><span>持久存储</span><strong>{{bytes(state.storageBytes)}}</strong><small>额度 {{bytes(state.storageLimitBytes)}}</small></article><article class="stat-card"><span>原文与未完成投递载荷</span><strong>{{bytes(state.queueBytes)}}</strong><small>含现存原文，不等于未确认事件数</small></article><article class="stat-card"><span>最老待投递时长</span><strong>{{state.oldestPendingAgeSeconds}} <em>秒</em></strong><small>最近刷新 {{dateTime(at)}}</small></article></div>
 <div class="two-column"><section class="panel"><div class="section-title">组件状态</div><el-table :data="state.components"><el-table-column prop="name" label="组件"/><el-table-column label="当前状态"><template #default="s"><el-tag :type="s.row.state==='READY'?'success':'warning'">{{statusLabel(s.row.state)}}</el-tag></template></el-table-column><el-table-column prop="code" label="说明"/></el-table></section><section class="panel"><div class="section-title">数据节点与规则</div><div v-for="node in state.dataNodes" :key="node.dataNodeId" class="definition-block"><span class="muted">{{node.dataNodeId}}</span><strong class="mono">{{node.activeBundleId}}</strong><span>激活修订 {{node.activationRevision}}</span></div><el-empty v-if="!state.dataNodes.length" description="尚无已激活的数据节点"/></section></div>
 <section class="panel capacity-panel"><div><div class="section-title">磁盘余量</div><p class="muted">持久化之前检查存储额度和预留空间。达到限制时设备需保留并重试数据。</p></div><div class="capacity-value"><strong>{{bytes(state.diskFreeBytes)}}</strong><span>可用 · 软件预留 {{bytes(state.diskReserveBytes)}}</span></div></section></template><el-skeleton v-else-if="busy" :rows="8" animated/></template>
